{
  "root_causes": [
    {
      "service": "product-catalog",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_span_kind, count(*) AS n FROM abnormal_traces WHERE service_name='product-catalog' GROUP BY 1,2",
          "claim": "product-catalog emits no spans at all in the abnormal window; it served no requests (normal had 60 server spans)."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name caller, span_name, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs, round(avg(duration)/1e6,2) avg_ms FROM abnormal_traces WHERE attr_span_kind='Client' AND span_name LIKE '%ProductCatalogService%' GROUP BY 1,2 ORDER BY 1,2",
          "claim": "Every call from checkout, frontend and recommendation to ProductCatalogService fails (errs = n) in about 0.1–0.7 ms."
        },
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_pod_name pod, metric, count(*) n, round(avg(value),1) avgv FROM abnormal_metrics WHERE metric IN ('k8s.container.restarts') AND attr_k8s_pod_name LIKE 'product-catalog%' GROUP BY 1,2",
          "claim": "product-catalog container restarts rise to 2 in the abnormal window (1 in normal), and the pod keeps reporting."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'abn' p, metric, round(avg(value),1) avgv FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'product-catalog%' AND metric IN ('container.memory.rss','container.memory.working_set') GROUP BY 1,2 UNION ALL SELECT 'norm', metric, round(avg(value),1) FROM normal_metrics WHERE attr_k8s_pod_name LIKE 'product-catalog%' AND metric IN ('container.memory.rss','container.memory.working_set') GROUP BY 1,2",
          "claim": "product-catalog memory RSS falls from about 12 MB in normal to about 0.3 MB in abnormal, consistent with a restarted process that is not serving."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "product-catalog",
      "to": "recommendation",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name caller, span_name, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='recommendation' AND attr_span_kind='Client' GROUP BY 1,2",
          "claim": "All 37 recommendation calls to ProductCatalogService/ListProducts fail, and recommendation's get_product_list spans error too."
        }
      ]
    },
    {
      "from": "product-catalog",
      "to": "checkout",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name caller, span_name, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='checkout' AND attr_span_kind='Client' AND span_name LIKE '%ProductCatalogService%' GROUP BY 1,2",
          "claim": "All 18 checkout GetProduct calls to product-catalog fail, and checkout's server spans all end in error."
        }
      ]
    },
    {
      "from": "product-catalog",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name caller, span_name, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='frontend' AND attr_span_kind='Client' AND span_name LIKE '%ProductCatalogService%' GROUP BY 1,2",
          "claim": "All 169 frontend GetProduct calls to product-catalog fail, producing 500s on /api/products routes."
        }
      ]
    },
    {
      "from": "recommendation",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='frontend' AND span_name LIKE '%RecommendationService/ListRecommendations%' GROUP BY 1,2",
          "claim": "Frontend's calls to RecommendationService/ListRecommendations fail (63 of 63) after recommendation's upstream errors."
        }
      ]
    },
    {
      "from": "checkout",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='frontend' AND span_name LIKE '%CheckoutService/PlaceOrder%' GROUP BY 1,2",
          "claim": "Frontend's calls to CheckoutService/PlaceOrder all fail (43 of 43), with 500 responses on /api/checkout."
        }
      ]
    },
    {
      "from": "frontend",
      "to": "frontend-proxy",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_span_kind, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='frontend-proxy' AND attr_span_kind='Server' GROUP BY 1,2",
          "claim": "frontend-proxy server spans error on 239 of 378 requests in the abnormal window, versus 6 of 55 in normal."
        }
      ]
    }
  ]
}
